 for(let i=0;i<3;i++){let x=(i-1)*3.3;const group=new T.Group();scene.add(group);box(2,.15,1.8,x,0,0,i===step?0xd8f667:0xa7b59e);if(role.id==='frontend'||role.id==='qa'){box(1.6,1.5,.14,x,1,0,dark);box(1.42,1.28,.03,x,1,.09,0xf0f1e7);for(let j=0;j<3;j++)box(.9-j*.1,.09,.04,x-.12,1.4-j*.25,.12,i===step?0x9683b9:0xa3b789);box(.65,.21,.04,x,.55,.13,role.id==='qa'?0x9ab581:0xb4a1d3);if(role.id==='qa'&&i===1){const lens=new T.Mesh(new T.TorusGeometry(.35,.07,12,32),new T.MeshStandardMaterial({color:0x8da66d}));lens.position.set(x+.5,1.25,.4);scene.add(lens);box(.1,.5,.08,x+.78,.82,.4,dark).rotation.z=-.5;}}else if(role.id==='security'&&i===1){const shield=new T.Shape();shield.moveTo(-.7,1.6);shield.lineTo(.7,1.6);shield.lineTo(.65,.6);shield.lineTo(0,.1);shield.lineTo(-.65,.6);shield.closePath();const sh=new T.Mesh(new T.ExtrudeGeometry(shield,{depth:.2,bevelEnabled:false}),new T.MeshStandardMaterial({color:0xa793c6}));sh.position.x=x;scene.add(sh);box(.13,.65,.08,x,.9,.24,0xd8f667);box(.5,.13,.08,x,1,.24,0xd8f667);}else if(i===0){box(1.5,1,.13,x,1,0,dark);box(1.3,.8,.03,x,1,.08,boss?0xe8958a:0xb4c8d5);box(.1,.4,.1,x,.35,0,dark);box(1.1,.06,.65,x,.17,.3,dark);}else if(i===1){box(1.3,1.6,.9,x,.85,0,dark);for(let j=0;j<4;j++){box(1.1,.15,.05,x,.4+j*.32,.49,i===step?0xd8f667:0xa6b4bf);}}else{for(let j=0;j<3;j++){const m=new T.Mesh(new T.CylinderGeometry(.7,.7,.3,32),new T.MeshStandardMaterial({color:j===step?0xd8f667:0xa896c9}));m.position.set(x,.4+j*.4,0);scene.add(m);}}const ring=new T.Mesh(new T.TorusGeometry(1.15,.035,8,60),new T.MeshStandardMaterial({color:i===step?0xd8f667:0x879581}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.08,0);scene.add(ring);blocks.push(ring);}
 for(let i=0;i<2;i++)box(1.3,.04,.05,-1.65+i*3.3,.15,0,0x8ca16e);
 const packet=new T.Mesh(new T.SphereGeometry(.12,16,12),new T.MeshStandardMaterial({color:0xd8f667,emissive:0x889c48}));scene.add(packet);let raf;const start=performance.now();function draw(){raf=requestAnimationFrame(draw);if(document.hidden)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;if(canvas.width!==Math.floor(w*renderer.getPixelRatio())||canvas.height!==Math.floor(h*renderer.getPixelRatio()))renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();const t=(performance.now()-start)/1000;packet.position.set(-3.3+(t%4)/4*6.6,.35+Math.sin(t*4)*.06,.8);blocks[step%3].rotation.z=t*.1;renderer.render(scene,camera);}draw();return {dispose(){cancelAnimationFrame(raf);scene.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});renderer.dispose();}};
